('cbdd7dd8-6a38-56c0-9971-7f2d1b27c8ef', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Di dîroka siyasî ya Ewropayê de, di sala 1215an de kîjan papayî Magna Carta betal kiriye?', 'Papa Honorius III', 'Papa Innocentius III', 'Papa Gregorius IX', 'Papa Alexander III', 'B', 'Papa Innocentius III, di tebaxa sala 1215an de bi hinceta ku ev belge bi zorê ji padîşahî hatiye stendin, Magna Carta betal kir û diyar kir ku ew ne derbasdar e.', 'Papa Innocentius III, di tebaxa sala 1215an de bi hinceta ku ev belge bi zorê ji padîşahî hatiye stendin, Magna Carta betal kir û diyar kir ku ew ne derbasdar e.', 'Papa III. Innocentius, Ağustos 1215''te belgenin kraldan zorla alındığını öne sürerek Magna Carta''yı iptal etmiş ve geçersiz ilan etmiştir.', 5, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Magna_Carta', 'en.wikipedia.org', 'https://en.wikipedia.org/wiki/Magna_Carta', 'approved', 'Kurmancî', 2, now()),
('71ad79fb-9272-52f9-ad9c-0b542a3b33f8', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Di dîrokê de welatê yekem ê ku di hilbijartinan de mafê dengdanê daye jinan kîjan e?', 'Fransa', 'Norwêc', 'Zelanda Nû', 'Brîtanya', 'C', 'Di sala 1893an de Zelanda Nû bû welatê yekem ê ku mafê dengdanê yê jinan bi qanûnî qebûl kir.', 'Di sala 1893an de Zelanda Nû bû welatê yekem ê ku mafê dengdanê yê jinan bi qanûnî qebûl kir.', 'Yeni Zelanda, 1893 yılında çıkardığı yasayla kadınlara seçme hakkı tanıyan ilk ülke olmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Women%27s_suffrage', 'en.wikipedia.org', 'https://en.wikipedia.org/wiki/Women%27s_suffrage', 'approved', 'Kurmancî', 2, now()),
